import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer tokenizer = new StringTokenizer(line);
        if (!tokenizer.hasMoreTokens()) return;

        int n = Integer.parseInt(tokenizer.nextToken());
        String[] passwords = new String[n];
        HashMap<String, Integer> freq = new HashMap<>(n * 2);

        for (int i = 0; i < n; i++) {
            passwords[i] = reader.readLine().trim();
            freq.put(passwords[i], freq.getOrDefault(passwords[i], 0) + 1);
        }

        long totalPairs = 0;
        HashSet<String> uniqueSubstrings = new HashSet<>(64);

        for (int i = 0; i < n; i++) {
            String s = passwords[i];
            uniqueSubstrings.clear();
            int len = s.length();

            for (int start = 0; start < len; start++) {
                for (int end = start + 1; end <= len; end++) {
                    uniqueSubstrings.add(s.substring(start, end));
                }
            }

            for (String sub : uniqueSubstrings) {
                Integer count = freq.get(sub);
                if (count != null) {
                    if (sub.equals(s)) {
                        totalPairs += (count - 1);
                    } else {
                        totalPairs += count;
                    }
                }
            }
        }

        System.out.println(totalPairs);
    }
}
